const base="https://github.com/atharvasatishchaudhari/";
const images=["assets/reasoning.webp","assets/carelens-new.webp","assets/drbot-cover.webp","assets/skin-cancer-cover.webp","assets/furniture-new.webp","assets/lostfound-new.webp","assets/medihealth-new.webp","assets/award-new.webp"];
const durations=["January 2026 to April 2026","August 2025 to December 2025","June 2025 to July 2025","January 2023 to May 2023","August 2021 to December 2021","January 2025 to June 2025","August 2024 to December 2024","August 2024 to December 2024"];
const timelineRank=[0,1,2,6,7,3,4,5];
projects.forEach((p,i)=>{p.image=images[i];p.duration=durations[i];p.timelineRank=timelineRank[i]});
projects.sort((a,b)=>a.timelineRank-b.timelineRank);
const list=document.getElementById("projectList"),modal=document.getElementById("projectModal"),modalContent=document.getElementById("modalContent");
function cleanTypography(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())node.nodeValue=node.nodeValue.replace(/[—–-]/g," ").replace(/\s{2,}/g," ")}
function openProject(repo){const p=projects.find(x=>x.repo===repo);modalContent.innerHTML=`<img class="modal-image" src="${p.image}" alt="${p.title} project preview"><span class="modal-label">${p.label}</span><span class="modal-duration">${p.duration}</span><h3>${p.title}</h3><p class="modal-summary">${p.summary}</p><div class="highlights">${p.metrics.map(m=>`<div><strong>${m[0]}</strong><span>${m[1]}</span></div>`).join("")}</div><div class="case-grid"><div><h4>WHAT I BUILT</h4><ul>${p.details.map(x=>`<li>${x}</li>`).join("")}</ul></div><div><h4>TECHNICAL FLOW</h4><ol>${p.architecture.map(x=>`<li>${x}</li>`).join("")}</ol><div class="stack">${p.stack.map(x=>`<span>${x}</span>`).join("")}</div></div></div><div class="modal-links"><a href="${base+p.repo}" target="_blank" rel="noreferrer">View GitHub repository ↗</a>${p.links.map(x=>`<a href="${x[1]}" target="_blank" rel="noreferrer">${x[0]} ↗</a>`).join("")}</div>`;cleanTypography(modalContent);modal.classList.add("show");modal.setAttribute("aria-hidden","false");document.body.classList.add("locked")}
function renderProjects(filter="all"){const shown=filter==="all"?projects:projects.filter(p=>p.cat.includes(filter));list.innerHTML=shown.map(p=>`<button class="project-card" data-repo="${p.repo}"><div class="project-image"><img src="${p.image}" alt=""></div><div class="project-card-copy"><div class="project-meta"><small>${p.label}</small><time>${p.duration}</time></div><h3>${p.title}</h3><p>${p.summary}</p><span>View full case study ↗</span></div></button>`).join("");cleanTypography(list);list.querySelectorAll(".project-card").forEach(b=>b.onclick=()=>openProject(b.dataset.repo))}
document.querySelectorAll(".filters button").forEach(b=>b.onclick=()=>{document.querySelector(".filters .active").classList.remove("active");b.classList.add("active");renderProjects(b.dataset.filter)});document.querySelectorAll("[data-close]").forEach(x=>x.onclick=()=>{modal.classList.remove("show");modal.setAttribute("aria-hidden","true");document.body.classList.remove("locked")});addEventListener("keydown",e=>{if(e.key==="Escape")document.querySelector(".modal-close").click()});renderProjects();
